arguments.command:
curl -s -X POST "https://slack.com/api/search.messages" --data-urlencode "token=<TOKEN>" --data-urlencode "query=rollback in:C_INC" --data-urlencode "count=50" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print(json.dumps(d, indent=2)[:400])
else:
    for m in d.get('messages',{}).get('matches',[]):
        print(m.get('user'), m.get('ts'), m.get('channel'), '|', (m.get('text') or '')[:200].replace(chr(10),' '))
    print('total:', d.get('messages',{}).get('total'))
"

